M_{t}^{N,f} &= Y_{t}(f) - Y_{0}(f) - \int_{0}^{t} Y_{s}(\mathscr{L}^{N}f) \mathrm{d}s \\
N_{t}^{N,f} &= (M_{t}^{N,f})^{2} - \int_{0}^{t} \Gamma^{N,f}(s) \mathrm{d}s.
\end{aligned}
\end{equation}

With a slight abuse of notation, we interpret $M_{t}^{f}$ (similarly $M_{t}^{N,f}$, $N_{t}^{f}$, $N_{t}^{N,f}$) here as a function $\mathscr{D}([0,T],(C^{\infty})') \to \mathbb{R}$. When writing $\mathbb{E}_{N}M_{t}^{f}$ we mean the expectation of this function as a function of $Y^{N}$ and when writing $\mathbb{E}M_{t}^{f}$ we regard it as a function of the random element of $\mathscr{D}([0,T],(C^{\infty})')$ with law $\mathcal{L}^{*}$.

Fix $0 \leq s \leq t \leq T$. We want to show that under $\mathcal{L}^{*}$

\begin{equation}
\mathbb{E}[M_{t}^{f}|\mathscr{F}_{s}] = M_{s}^{f} \quad \text{and} \quad \mathbb{E}[N_{t}^{f}|\mathscr{F}_{s}] = N_{s}^{f}.
\end{equation}

Fix $n \in \mathbb{N}$, $s \geq 0$, $0 \leq s_{1} \leq .. \leq s_{n} \leq s$, $H_{1},..,H_{n} \in C^{\infty}$, $\Psi \in C_{b}(\mathbb{R}^{n})$ and define

\begin{equation}
\begin{aligned}
I: & \quad \mathscr{D}([0,T],(C^{\infty})') \to \mathbb{R} \\
I: & \quad Y \mapsto \Psi(Y_{s_{1}}(H_{1}),...,Y_{s_{n}}(H_{n})).
\end{aligned}
\end{equation}

Now it suffices to show that

\begin{equation}
\lim_{N \to \infty} \mathbb{E}_{N}M_{t}^{N,f}I(Y) = \mathbb{E}M_{t}^{f}I(Y), \qquad \lim_{N \to \infty} \mathbb{E}_{N}N_{t}^{N,f}I(Y) = \mathbb{E}N_{t}^{f}I(Y),
\tag{23}
\end{equation}

since then by the martingale property of $M_{t}^{N,f}$

\begin{equation}
\mathbb{E}M_{t}^{f}I(Y) = \lim_{N \to \infty} \mathbb{E}_{N}M_{t}^{N,f}I(Y) = \lim_{N \to \infty} \mathbb{E}_{N}M_{s}^{N,f}I(Y) = \mathbb{E}M_{s}^{f}I(Y)
\end{equation}

and analogous for the $N_{t}^{f}$ case, which implies that $M_{t}^{f}$ and $N_{t}^{f}$ are martingales under $\mathcal{L}^{*}$.

We start with the first martingale. First we show that we can replace $M_{t}^{N,f}$ by $M_{t}^{f}$ in the first expectation in (23). Using Jensen we see that

\begin{equation}
\left(\mathbb{E}_{N}M_{t}^{N,f}I(Y) - \mathbb{E}_{N}M_{t}^{f}I(Y)\right)^{2} \leq \|\Psi\|_{\infty}^{2} \mathbb{E}_{N}(M_{t}^{N,f} - M_{t}^{f})^{2} = \|\Psi\|_{\infty}^{2} \mathbb{E}_{N}\left(\int_{0}^{t} Y_{s}(\Delta_{M}f) \mathrm{d}s - \int_{0}^{t} Y_{s}(\mathscr{L}^{N}f) \mathrm{d}s\right)^{2},
\end{equation}

which goes to 0 by lemma 3.1. Now it remains to show that

\begin{equation}
\lim_{N \to \infty} \mathbb{E}_{N}M_{t}^{f}I(Y) = \mathbb{E}M_{t}^{f}I(Y).
